class Lampe1 {
   Rechteck kasten;
   Kreis licht;

   Lampe1() {
      kasten = new Rechteck();
      kasten.GrößeSetzen(50, 50);
      kasten.PositionSetzen(100, 100);
      kasten.FarbeSetzen("schwarz");
      licht = new Kreis();
      licht.RadiusSetzen(20);
      licht.PositionSetzen(125, 125);
      licht.FarbeSetzen("rot");
   } 

   void RotLeuchten() {
      licht.FarbeSetzen("rot");
   }

   void GelbLeuchten() {
      licht.FarbeSetzen("gelb");
   }

   void GrünLeuchten() {
      licht.FarbeSetzen("grün");
   }

   void Ausschalten() {
      licht.FarbeSetzen("grau");
   }

   void PositionSetzen(int posXneu, int posYneu) {
      kasten.PositionSetzen(posXneu-25, posYneu-25);
      licht.PositionSetzen(posXneu, posYneu); 
   }
}

