class Ampel {
   String ampelphase;
   int posX;
   int posY;

   Lampe l1;
   Lampe l2;
   Lampe l3;

   Ampel() {
      ampelphase = "rot";
      posX = 100;
      posY = 100;
      ampelphase;
      l1 = new Lampe();
      l1.RotLeuchten();
      l1.PositionSetzen(100, 100);
      l2 = new Lampe();
      l2.Ausschalten();
      l2.PositionSetzen(100, 140);
      l3 = new Lampe();
      l3.Ausschalten();
      l3.PositionSetzen(100, 180); 
   }

   void PositionSetzen(int posXneu, int posYneu) {
      posX = posXneu;
      posY = posYneu;
      l1.PositionSetzen(posX, posY);
      l2.PositionSetzen(posX, posY + 40);
      l3.PositionSetzen(posX, posY + 80);
   }

   void RotSetzen() {
      ampelphase = "rot";
      l1.RotLeuchten();
      l2.Ausschalten();
      l3.Ausschalten(); 
   }

   void RotGelbSetzen() {
      ampelphase = "rotgelb";
      l1.RotLeuchten();
      l2.GelbLeuchten();
      l3.Ausschalten(); 
   }

   void GelbSetzen() {
      ampelphase = "gelb";
      l1.Ausschalten();
      l2.GelbLeuchten();
      l3.Ausschalten(); 
   }

   void GrünSetzen() {
      ampelphase = "grün";
      l1.Ausschalten();
      l2.Ausschalten();
      l3.GrünLeuchten(); 
   }

   void Weiterschalten() {
      if(ampelphase == "rot") {
         RotGelbSetzen();
      }
      else if(ampelphase == "rotgelb") {
         GrünSetzen();
      }
      else if(ampelphase == "grün") {
         GelbSetzen();
      } 
      else {
         RotSetzen();
      }
   }

   void RichtungSetzen(char richtungneu) {
      switch(richtungneu) {
         case 'N' : 
            l1.PositionSetzen(posX, posY);
            l2.PositionSetzen(posX, posY - 40);
            l3.PositionSetzen(posX, posY - 80);
            break;
         case 'W' : 
            l1.PositionSetzen(posX, posY);
            l2.PositionSetzen(posX - 40, posY);
            l3.PositionSetzen(posX - 80, posY); 
            break;
         case 'O' : 
            l1.PositionSetzen(posX, posY);
            l2.PositionSetzen(posX + 40, posY);
            l3.PositionSetzen(posX + 80, posY); 
            break;
         default : 
            PositionSetzen(posX, posY);
      }

   }
}

