class Lampe extends Figur {

   Lampe() {
      super();
      this.FigurteilFestlegenRechteck(0, 0, 100, 100, "schwarz");
      this.FigurteilFestlegenEllipse(10, 10, 80, 80, "rot"); 
   }

   void RotLeuchten() {
      this.EigeneFigurLöschen();
      this.FigurteilFestlegenRechteck(0, 0, 100, 100, "schwarz");
      this.FigurteilFestlegenEllipse(10, 10, 80, 80, "rot"); 
   }

   void GelbLeuchten() {
      this.EigeneFigurLöschen();
      this.FigurteilFestlegenRechteck(0, 0, 100, 100, "schwarz");
      this.FigurteilFestlegenEllipse(10, 10, 80, 80, "gelb"); 
   }

   void GrünLeuchten() {
      this.EigeneFigurLöschen();
      this.FigurteilFestlegenRechteck(0, 0, 100, 100, "schwarz");
      this.FigurteilFestlegenEllipse(10, 10, 80, 80, "grün"); 
   }

   void Ausschalten() {
      this.EigeneFigurLöschen();
      this.FigurteilFestlegenRechteck(0, 0, 100, 100, "schwarz");
      this.FigurteilFestlegenEllipse(10, 10, 80, 80, "grau"); 
   }

   @Override void PositionSetzen(int x, int y) {
      super.PositionSetzen(x - 20, y - 20); 
   } 
}
